-- Runs once when the Postgres container is first created.
-- 1. Load the demo data (generated by scripts/make_demo_db.py).
\i /docker-entrypoint-initdb.d/data/shop_postgres.sql

-- 2. A role that can only read. This is the real safety boundary for the agent;
--    read-only transactions and the SQL guard are defence in depth.
CREATE ROLE t2s_reader LOGIN PASSWORD 'reader_password';
GRANT CONNECT ON DATABASE shop TO t2s_reader;
GRANT USAGE ON SCHEMA public TO t2s_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO t2s_reader;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
ALTER ROLE t2s_reader SET default_transaction_read_only = on;
ALTER ROLE t2s_reader SET statement_timeout = '10s';
ALTER ROLE t2s_reader SET idle_in_transaction_session_timeout = '30s';
